with city_rows(name,slug) as (values ('Auckland','auckland'),('Hamilton','hamilton'),('Palmerston North','palmerston-north'),('Wellington','wellington'),('Christchurch','christchurch'),('Lincoln','lincoln'),('Dunedin','dunedin')) insert into core.geographies(id,country_code,geography_type,name,slug,metadata,status) select md5('nz:city:'||slug)::uuid,'NZ','city',name,slug,jsonb_build_object('source_tier','government_registry','registry_system','NZQA','normalization_batch','nz_university_locations_v1'),'active' from city_rows on conflict (id) do update set name=excluded.name,slug=excluded.slug,metadata=coalesce(core.geographies.metadata,'{}'::jsonb)||excluded.metadata,status=excluded.status,updated_at=now(); with location_rows(provider_number,city_name,city_slug) as (values ('7001','Auckland','auckland'),('7008','Auckland','auckland'),('7002','Hamilton','hamilton'),('7003','Palmerston North','palmerston-north'),('7004','Wellington','wellington'),('7005','Christchurch','christchurch'),('7006','Lincoln','lincoln'),('7007','Dunedin','dunedin')), resolved as (select identity.institution_id,identity.provider_number,identity.provider_source_url,i.website_url,l.city_name,l.city_slug,g.id geography_id from location_rows l join public.institution_identity_nz_v1 identity on identity.provider_number=l.provider_number join catalog.institutions i on i.id=identity.institution_id join core.geographies g on g.country_code='NZ' and g.geography_type='city' and g.slug=l.city_slug and g.status='active') insert into catalog.campuses(id,institution_id,name,city,locality,country_code,geography_id,locality_geography_id,official_url,source_url,source_checked_at,metadata,status) select md5('nz:registered-location:'||provider_number)::uuid,institution_id,'Registered institution location',city_name,city_name,'NZ',geography_id,geography_id,website_url,provider_source_url,now(),jsonb_build_object('record_scope','registered_institution_location','location_quality','verified_registry_city','display_policy','preferred','source_tier','government_registry','registry_system','NZQA','provider_number',provider_number,'location_key','nzqa-head-office-city','coordinate_precision','not_asserted','programme_assignment_verified',false,'normalization_batch','nz_university_locations_v1'),'active' from resolved on conflict (id) do update set name=excluded.name,city=excluded.city,locality=excluded.locality,geography_id=excluded.geography_id,locality_geography_id=excluded.locality_geography_id,official_url=excluded.official_url,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at,metadata=excluded.metadata,status=excluded.status,updated_at=now(); create or replace view public.institution_location_nz_v1 with (security_invoker=true) as select c.institution_id,c.id campus_id,c.name,g.name city_name,g.slug city_slug,coalesce(nullif(c.city,''),nullif(c.locality,'')) reported_city,c.region,c.address_line,c.postal_code,c.official_url,c.source_url,c.source_checked_at,c.metadata->>'location_quality' location_quality,c.metadata->>'record_scope' record_scope,c.metadata->>'provider_number' provider_number from catalog.campuses c join catalog.institutions i on i.id=c.institution_id and i.country_code='NZ' left join core.geographies g on g.id=coalesce(c.locality_geography_id,c.geography_id) and g.status='active' where c.status<>'inactive' and c.metadata->>'location_quality'='verified_registry_city'; revoke all on public.institution_location_nz_v1 from public,anon,authenticated; grant select on public.institution_location_nz_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_location_nz_v1; if c<>8 then raise exception 'Expected 8 NZ registry locations, found %',c; end if; select count(*) into c from catalog.campuses cp join catalog.institutions i on i.id=cp.institution_id where i.country_code='NZ' and cp.status<>'inactive' and cp.metadata->>'location_quality'='verified_registry_city' and (cp.latitude is not null or cp.longitude is not null); if c>0 then raise exception 'NZ registry locations assert coordinates %',c; end if; end $$;;
